draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw rich dad
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 - 15, H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 30);
  ctx.lineTo(W/4 + 15, H/2 + 45);
  ctx.stroke();

  // Draw money bag
  ctx.beginPath();
  ctx.arc(W/4 + 30, H/2 + 60, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 + 30, H/2 + 75);
  ctx.lineTo(W/4 + 30, H/2 + 90);
  ctx.stroke();

  // Draw poor dad
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 - 15, H/2 + 45);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 30);
  ctx.lineTo(W - W/4 + 15, H/2 + 45);
  ctx.stroke();

  // Draw debt
  ctx.beginPath();
  ctx.arc(W - W/4 - 30, H/2 + 60, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 - 30, H/2 + 75);
  ctx.lineTo(W - W/4 - 30, H/2 + 90);
  ctx.stroke();

  // animate rich dad and poor dad
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 50);
  ctx.lineTo(W - W/4, H/2 + 50);
  ctx.lineWidth = 2;
  ctx.strokeStyle = 'black';
  ctx.stroke();
  ctx.lineWidth = 4;

  // animate money and debt
  ctx.beginPath();
  ctx.arc(W/4 + 30 + Math.sin(t) * 10, H/2 + 60, 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W - W/4 - 30 + Math.cos(t) * 10, H/2 + 60, 15, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
